'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var absf = require( '@stdlib/math/base/special/absf' );
var sincosf = require( '@stdlib/math/base/special/sincosf' ).assign;
var floorf = require( '@stdlib/math/base/special/floorf' );
var PI = require( '@stdlib/constants/float32/pi' );
var copysignf = require( '@stdlib/math/base/special/copysignf' );


// MAIN //

/**
* Simultaneously computes the sine and cosine of a number times π (single-precision).
*
* @private
* @param {number} x - input value
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array index offset
* @returns {Collection} two-element array containing sin(πx) and cos(πx)
*
* @example
* var v = sincospif( 0.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ 0.0, 1.0 ]
*
* @example
* var v = sincospif( 0.5, [ 0.0, 0.0 ], 1, 0 );
* // returns [ 1.0, 0.0 ]
*
* @example
* var v = sincospif( 0.1, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~0.309, ~0.951 ]
*
* @example
* var v = sincospif( NaN, [ 0.0, 0.0 ], 1, 0 );
* // returns [ NaN, NaN ]
*/
function sincospif( x, out, stride, offset ) {
	var tmp;
	var ix;
	var ar;
	var r;

	if ( isnanf( x ) || isInfinitef( x ) ) {
		out[ offset ] = NaN;
		out[ offset + stride ] = NaN;
		return out;
	}

	r = x % 2.0;
	ar = absf( r );

	if ( ar === 0.0 || ar === 1.0 ) {
		ix = floorf( ar );
		out[ offset ] = copysignf( 0.0, r );
		out[ offset + stride ] = ( ix%2 === 1 ) ? -1.0 : 1.0;
		return out;
	}

	if ( ar < 0.25 ) {
		return sincosf( PI*r, out, stride, offset );
	}
	if ( ar < 0.75 ) {
		ar = 0.5 - ar;
		sincosf( PI*ar, out, stride, offset );
		tmp = out[ offset ];
		out[ offset ] = copysignf( out[ offset + stride ], r );
		out[ offset + stride ] = tmp;
		return out;
	}
	if ( ar < 1.25 ) {
		r = copysignf( 1.0, r ) - r;
		sincosf( PI*r, out, stride, offset );
		out[ offset + stride ] *= -1;
		return out;
	}
	if ( ar < 1.75 ) {
		ar -= 1.5;
		sincosf( PI*ar, out, stride, offset );
		tmp = out[ offset ];
		out[ offset ] = -copysignf( out[ offset + stride ], r );
		out[ offset + stride ] = tmp;
		return out;
	}

	r -= copysignf( 2.0, r );
	return sincosf( PI*r, out, stride, offset );
}


// EXPORTS //

module.exports = sincospif;
